package br.com.agendapp.domain

import org.junit.Test
import org.junit.Assert.*
import java.time.*

class DomainTest {
    private val start=LocalDate.of(2024,1,31)
    private val zone=ZoneId.of("America/Sao_Paulo")
    private fun dates(rule: Rule,from: LocalDate=start,to: LocalDate=from.plusMonths(4)) = Recurrence.dates(from,rule,to).toList()
    private fun series(rule: Rule=Rule()): Series { val event=Event(date="2026-01-01",name="Médico",start="09:00",reminders=listOf(Reminder()),tasks=listOf(Task(name="Preparar")));return Series(segments=listOf(Segment(from=event.date,template=event,rule=rule))) }
    private fun state(s: Series)=State(series=listOf(s))
    private fun occurrence(s: Series,date: String)=Recurrence.onDay(state(s),LocalDate.parse(date)).single()
    @Test fun monthlyClampsWithoutDrifting() { assertEquals(listOf("2024-01-31","2024-02-29","2024-03-31","2024-04-30","2024-05-31"),dates(Rule(frequency=Frequency.MONTHLY)).map{it.toString()}) }
    @Test fun yearlyLeapDayClamps() { assertEquals(listOf("2024-02-29","2025-02-28","2026-02-28"),dates(Rule(frequency=Frequency.YEARLY),LocalDate.parse("2024-02-29"),LocalDate.parse("2026-03-01")).map{it.toString()}) }
    @Test fun everyThreeDaysAndCount() { assertEquals(listOf(start,start.plusDays(3),start.plusDays(6)),dates(Rule(interval=3,count=3))) }
    @Test fun everyTwoWeeksSelectedDays() { val d=dates(Rule(frequency=Frequency.WEEKLY,interval=2,weekdays=setOf(1,5)),LocalDate.parse("2026-01-05"),LocalDate.parse("2026-01-25"));assertEquals(listOf("2026-01-05","2026-01-09","2026-01-19","2026-01-23"),d.map{it.toString()}) }
    @Test fun secondTuesday() { assertEquals(listOf("2026-01-13","2026-02-10","2026-03-10"),dates(Rule(frequency=Frequency.MONTHLY,ordinal=2,weekday=2),LocalDate.parse("2026-01-01"),LocalDate.parse("2026-03-31")).map{it.toString()}) }
    @Test fun missingFifthWeekdayIsSkipped() { assertEquals(listOf("2026-03-31"),dates(Rule(frequency=Frequency.MONTHLY,ordinal=5,weekday=2),LocalDate.parse("2026-01-01"),LocalDate.parse("2026-03-31")).map{it.toString()}) }
    @Test fun endDateInclusive() { assertEquals(2,dates(Rule(until="2024-02-01")).size) }
    @Test fun stableIndependentOccurrences() { val s=series();val a=occurrence(s,"2026-01-01");val b=occurrence(s,"2026-01-02");assertNotEquals(a.id,b.id);assertNotEquals(a.tasks.single().id,b.tasks.single().id);assertEquals(a,occurrence(s,"2026-01-01")) }
    @Test fun checklistCountsOnlyLeaves() { val parent=Task();val a=Task(parentId=parent.id,done=true);val b=Task(parentId=parent.id);assertEquals(1 to 2,Checklist.progress(listOf(parent,a,b))) }
    @Test fun completionPropagatesBothDirections() { val parent=Task();val mid=Task(parentId=parent.id);val leaf=Task(parentId=mid.id);val event=Event(date="2026-01-01",tasks=listOf(parent,mid,leaf));val done=Checklist.toggle(event,parent.id,true);assertTrue(done.done);assertTrue(done.tasks.all{it.done});val reopened=Checklist.toggle(done,leaf.id,false);assertFalse(reopened.done);assertTrue(reopened.tasks.none{it.done}) }
    @Test fun finalChildCompletesParent() { val p=Task();val a=Task(parentId=p.id,done=true);val b=Task(parentId=p.id);val e=Checklist.toggle(Event(date="2026-01-01",tasks=listOf(p,a,b)),b.id,true);assertTrue(e.done);assertTrue(e.tasks.first().done) }
    @Test fun manualCompletionMayKeepPending() { val e=Event(date="2026-01-01",tasks=listOf(Task()));val done=Checklist.complete(e,false);assertTrue(done.done);assertFalse(done.tasks.single().done);assertFalse(Checklist.toggle(done,done.tasks.single().id,false).done) }
    @Test fun manualNoChecklistNeverAutoCompletes() { val e=Event(date="2020-01-01",start="00:00");val s=Engine.save(State(),e,null,Scope.ONLY,LocalDate.now());assertFalse(s.events.single().done) }
    @Test fun rejectCircularMoves() { val p=Task();val child=Task(parentId=p.id);assertThrows(IllegalArgumentException::class.java){Checklist.move(listOf(p,child),p.id,child.id,null)} }
    @Test fun moveAndReorder() { val a=Task(position=0);val b=Task(position=1);val c=Task(position=2);val moved=Checklist.move(listOf(a,b,c),c.id,null,a.id);assertEquals(listOf(c.id,a.id,b.id),Checklist.ordered(moved).map{it.first.id}) }
    @Test fun supportsDeepTrees() { var parent: String?=null;val tasks=(1..200).map{Task(parentId=parent).also{parent=it.id}};assertEquals(1,Checklist.progress(tasks).second);assertEquals(199,Checklist.ordered(tasks).last().second);assertTrue(Checklist.toggle(Event(date="2026-01-01",tasks=tasks),tasks.first().id,true).done) }
    @Test fun occurrenceCompletionDoesNotAffectTomorrow() { val s=series();val e=occurrence(s,"2026-01-01");val updated=Engine.put(state(s),Checklist.complete(e,true));assertTrue(Recurrence.onDay(updated,LocalDate.parse(e.date)).single().done);assertFalse(Recurrence.onDay(updated,LocalDate.parse("2026-01-02")).single().done) }
    @Test fun onlyOccurrenceEditKeepsOtherDates() { val s=series();val e=occurrence(s,"2026-01-02").copy(name="Mudou");val n=Engine.save(state(s),e,Rule(),Scope.ONLY,LocalDate.parse("2026-01-01"));assertEquals("Mudou",Recurrence.onDay(n,LocalDate.parse(e.date)).single().name);assertEquals("Médico",Recurrence.onDay(n,LocalDate.parse("2026-01-03")).single().name) }
    @Test fun futureEditPreservesCompletionAndAvoidsDuplicates() { val s=series();val first=Checklist.complete(occurrence(s,"2026-01-01"),true);val old=Engine.put(state(s),first);val e=occurrence(s,"2026-01-03").copy(name="Novo");val n=Engine.save(old,e,Rule(interval=2),Scope.FUTURE,LocalDate.parse("2026-01-03"));assertTrue(Recurrence.onDay(n,LocalDate.parse("2026-01-01")).single().done);assertEquals(1,Recurrence.onDay(n,LocalDate.parse("2026-01-03")).size);assertTrue(Recurrence.onDay(n,LocalDate.parse("2026-01-04")).isEmpty());assertEquals("Novo",Recurrence.onDay(n,LocalDate.parse("2026-01-05")).single().name) }
    @Test fun entireSeriesEditPreservesPartialHistory() { val s=series();val oldEvent=occurrence(s,"2026-01-01").copy(notes="Histórico");val old=Engine.put(state(s),oldEvent);val n=Engine.save(old,occurrence(s,"2026-01-04").copy(name="Novo"),Rule(),Scope.ALL,LocalDate.parse("2026-01-04"));val preserved=Recurrence.onDay(n,LocalDate.parse("2026-01-01")).single();assertEquals(oldEvent.tasks,preserved.tasks);assertEquals("Novo",preserved.name);assertFalse(preserved.done) }
    @Test fun deleteOneAndRestore() { val s=series();val e=occurrence(s,"2026-01-02");val n=Engine.delete(state(s),e,Scope.ONLY);assertTrue(Recurrence.onDay(n,LocalDate.parse(e.date)).isEmpty());assertEquals(1,Recurrence.onDay(n,LocalDate.parse("2026-01-03")).size);val restored=Engine.restore(n,n.trash.single());assertEquals(e,Recurrence.onDay(restored,LocalDate.parse(e.date)).single()) }
    @Test fun deleteFutureAndRestorePhase() { val s=series(Rule(interval=3));val n=Engine.delete(state(s),occurrence(s,"2026-01-07"),Scope.FUTURE);assertEquals(1,Recurrence.onDay(n,LocalDate.parse("2026-01-04")).size);assertEquals(0,Recurrence.onDay(n,LocalDate.parse("2026-01-10")).size);val restored=Engine.restore(n,n.trash.single());assertEquals(1,Recurrence.onDay(restored,LocalDate.parse("2026-01-10")).size);assertEquals(0,Recurrence.onDay(restored,LocalDate.parse("2026-01-11")).size) }
    @Test fun deleteWholeSeriesAndRestoreOverrides() { val s=series();val e=Checklist.complete(occurrence(s,"2026-01-01"),true);val n=Engine.delete(Engine.put(state(s),e),e,Scope.ALL);assertTrue(n.events.isEmpty());assertTrue(n.series.isEmpty());val r=Engine.restore(n,n.trash.single());assertTrue(Recurrence.onDay(r,LocalDate.parse(e.date)).single().done) }
    @Test fun taskTrashRestoresDescendants() { val p=Task();val c=Task(parentId=p.id);val e=Event(date="2026-01-01",tasks=listOf(p,c));val n=Engine.deleteTask(Engine.put(State(),e),e,p.id);assertTrue(n.events.single().tasks.isEmpty());assertEquals(2,Engine.restore(n,n.trash.single()).events.single().tasks.size) }
    @Test fun orphanTaskRestoreDoesNotLoseData() { val e=Event(date="2026-01-01",tasks=listOf(Task()));val n=Engine.deleteTask(Engine.put(State(),e),e,e.tasks.single().id).copy(events=emptyList());assertThrows(IllegalStateException::class.java){Engine.restore(n,n.trash.single())};assertEquals(1,n.trash.size) }
    @Test fun expiresAtThirtyDays() { val t=Trash(deletedAt=1000,event=Event(date="2026-01-01"));assertEquals(1,Engine.expire(State(trash=listOf(t)),1000+Duration.ofDays(30).toMillis()-1).trash.size);assertEquals(0,Engine.expire(State(trash=listOf(t)),1000+Duration.ofDays(30).toMillis()).trash.size) }
    @Test fun pendingKeepsOriginalDate() { val e=Event(date="2026-01-01");assertEquals(e.date,Recurrence.pending(State(events=listOf(e)),LocalDate.parse("2026-01-03")).single().date) }
    @Test fun summaryIncludesDoneMainEventsOnly() { val s=series();val e=Event(date="2026-01-02",done=true,tasks=listOf(Task()));assertEquals(2,Recurrence.onDay(State(events=listOf(e),series=listOf(s)),LocalDate.parse(e.date)).size);assertEquals("Hoje você tem 1 compromisso.",Engine.summary(1,false));assertEquals("Amanhã você não tem compromissos.",Engine.summary(0,true)) }
    @Test fun remindersNeverRetroactive() { val e=Event(date="2026-01-01",start="09:00",reminders=listOf(Reminder()));assertTrue(ReminderPlanner.event(e,Instant.parse("2026-01-01T12:00:00Z"),zone).isEmpty()) }
    @Test fun remindersRequireTimeAndCancelOnDone() { val e=Event(date="2026-01-01",reminders=listOf(Reminder()));assertTrue(ReminderPlanner.event(e,Instant.EPOCH,zone).isEmpty());assertTrue(ReminderPlanner.event(e.copy(start="09:00",done=true),Instant.EPOCH,zone).isEmpty()) }
    @Test fun reopeningRestoresEligibleReminders() { val e=Event(date="2026-01-01",start="09:00",reminders=listOf(Reminder()),done=true);assertEquals(1,ReminderPlanner.event(Checklist.reopen(e),Instant.EPOCH,zone).size) }
    @Test fun completedSubtreeCancelsReminders() { val p=Task(time="09:00",reminders=listOf(Reminder()));val c=Task(parentId=p.id,time="10:00",reminders=listOf(Reminder()));val e=Event(date="2026-01-01",tasks=listOf(p,c));assertEquals(2,ReminderPlanner.event(e,Instant.EPOCH,zone).size);assertTrue(ReminderPlanner.event(Checklist.toggle(e,p.id,true),Instant.EPOCH,zone).isEmpty()) }
    @Test fun reminderIdsCannotOverwriteEachOther() { val e=Event(date="2026-01-01",start="09:00",reminders=listOf(Reminder(),Reminder()));assertEquals(2,ReminderPlanner.event(e,Instant.EPOCH,zone).map{it.id}.distinct().size) }
    @Test fun absoluteDoesNotRepeatAcrossSeries() { val base=Event(date="2026-01-01",start="09:00",reminders=listOf(Reminder(beforeMinutes=null,absolute="2026-01-01T08:00")));val s=Series(segments=listOf(Segment(from=base.date,template=base,rule=Rule())));assertEquals(1,occurrence(s,base.date).reminders.size);assertTrue(occurrence(s,"2026-01-02").reminders.isEmpty()) }
    @Test fun daylightSavingUsesLocalClockAndValidOffset() { val z=ZoneId.of("America/New_York");val r=Reminder(beforeMinutes=0);assertEquals(Instant.parse("2026-03-08T07:30:00Z"),ReminderPlanner.moment("2026-03-08","02:30",r,z));assertEquals(Instant.parse("2026-11-01T05:30:00Z"),ReminderPlanner.moment("2026-11-01","01:30",r,z)) }
    @Test fun timezoneChangesInstant() { val r=Reminder(beforeMinutes=15);assertNotEquals(ReminderPlanner.moment("2026-01-01","09:00",r,zone),ReminderPlanner.moment("2026-01-01","09:00",r,ZoneId.of("Europe/Lisbon"))) }
    @Test fun finiteAlarmWindowWithInfiniteRecurrence() { val s=series();val alarms=ReminderPlanner.window(state(s),Settings(),Instant.parse("2026-01-01T00:00:00Z"),zone);assertTrue(alarms.size<25);assertEquals(alarms.size,alarms.map{it.id}.distinct().size) }
    @Test fun backupRoundTripEverything() { val s=series();val e=Checklist.complete(occurrence(s,"2026-01-01"),true);val b=Backup(state=Engine.delete(Engine.put(state(s),e),e,Scope.ONLY),settings=Settings(dark=true));assertEquals(b,BackupCodec.decode(BackupCodec.encode(b))) }
    @Test fun rejectBackupVersionAndInvalidReferences() { assertThrows(IllegalArgumentException::class.java){BackupCodec.validate(Backup(version=2))};val p=Task(parentId=uid());assertThrows(IllegalArgumentException::class.java){BackupCodec.validate(Backup(state=State(events=listOf(Event(date="2026-01-01",tasks=listOf(p))))))} }
    @Test fun rejectCyclesInJson() { val id=uid();val e=Event(date="2026-01-01",tasks=listOf(Task(id=id,parentId=id)));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(BackupCodec.encode(Backup(state=State(events=listOf(e)))))} }
    @Test fun mergeNoDuplicatesAndExplicitConflictPolicy() { val e=Event(date="2026-01-01",name="Local");val a=Backup(state=State(events=listOf(e)));val b=Backup(state=State(events=listOf(e.copy(name="Importado"))));assertEquals(1,BackupCodec.conflicts(a,b));assertEquals("Local",BackupCodec.merge(a,b,false).state.events.single().name);assertEquals("Importado",BackupCodec.merge(a,b,true).state.events.single().name);assertEquals(a,BackupCodec.merge(a,a,true)) }
    @Test fun invalidImportIsRejectedBeforeChangingLocal() { val a=Backup(state=State(events=listOf(Event(date="2026-01-01"))));val bad=Backup(state=State(events=listOf(Event(id="bad",date="2026-01-01"))));assertThrows(IllegalArgumentException::class.java){BackupCodec.merge(a,bad,true)};assertEquals(1,a.state.events.size) }
    @Test fun searchIgnoresAccentsAndCase() { assertEquals("reuniao",Engine.fold("REUNIÃO")) }
    @Test fun rejectIncompleteBackupInsteadOfInventingIds() { assertThrows(IllegalArgumentException::class.java){BackupCodec.decode("{}")};val b=Backup(state=State(events=listOf(Event(date="2026-01-01"))));val json=BackupCodec.encode(b).replace(Regex("\"id\": \"[^\"]+\",?"), "");assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(json)} }
    @Test fun absoluteTaskReminderBelongsToFirstOccurrence() { val task=Task(time="09:00",reminders=listOf(Reminder(beforeMinutes=null,absolute="2026-01-01T08:00")));val base=Event(date="2026-01-01",tasks=listOf(task));val s=Series(segments=listOf(Segment(from=base.date,template=base,rule=Rule())));assertEquals(1,occurrence(s,base.date).tasks.single().reminders.size);assertTrue(occurrence(s,"2026-01-02").tasks.single().reminders.isEmpty()) }
    @Test fun farFutureEventWithEarlyReminderFitsWindow() { val e=Event(date="2026-03-02",start="09:00",reminders=listOf(Reminder(beforeMinutes=60*1440)));val result=ReminderPlanner.window(State(events=listOf(e)),Settings(),Instant.parse("2026-01-01T00:00:00Z"),zone);assertTrue(result.any { it.eventId==e.id }) }
    @Test fun relativeRecurringReminderCanPrecedeOccurrenceWindow() { val s=series().let { series -> series.copy(segments=series.segments.map { it.copy(from="2026-03-02",template=it.template.copy(date="2026-03-02",reminders=listOf(Reminder(beforeMinutes=60*1440)))) }) };val result=ReminderPlanner.window(state(s),Settings(),Instant.parse("2026-01-01T00:00:00Z"),zone);assertTrue(result.any{it.eventId!=null}) }
    @Test fun absoluteReminderForFarFutureEventIsScheduledNow() { val e=Event(date="2027-01-01",start="09:00",reminders=listOf(Reminder(beforeMinutes=null,absolute="2026-01-02T09:00")));assertTrue(ReminderPlanner.window(State(events=listOf(e)),Settings(),Instant.parse("2026-01-01T00:00:00Z"),zone).any{it.eventId==e.id}) }
    @Test fun editingContentKeepsRemainingOccurrenceCount() { val s=series(Rule(count=3));val n=Engine.save(state(s),occurrence(s,"2026-01-02").copy(name="Mudou"),Rule(count=3),Scope.FUTURE,LocalDate.parse("2026-01-02"));assertEquals(3,Recurrence.allThrough(n,LocalDate.parse("2026-02-01")).size) }
    @Test fun creationRejectsInitialDateOutsideRule() { val e=Event(date="2026-01-01");assertThrows(IllegalArgumentException::class.java){Engine.save(State(),e,Rule(frequency=Frequency.WEEKLY,weekdays=setOf(1)),Scope.ONLY,LocalDate.parse(e.date))} }
    @Test fun finalTimeValidation() { assertThrows(IllegalArgumentException::class.java){Engine.validateEvent(Event(date="2026-01-01",start="18:00",end="08:00"))};Engine.validateEvent(Event(date="2026-01-01",end="18:00")) }
}
